value.string:
{
 "type": "function",
 "function": {
 "name": "ERP5Document_doAction",
 "description": "Perform any action on a module or document: create a new document inside it, invoke a workflow transition (e.g. 'plan', 'confirm', 'start', 'stop', 'validate', 'deliver'), or invoke a custom object action. Call ERP5Document_getActionList on the same relative_url first to find which action_id values are currently valid (including 'add <portal_type>' entries built from can_create_here) and, if an action opens a dialog, which extra field values (dialog_field_list) it expects - pass those as extra keyword arguments here (for 'add <portal_type>', they become the new document's field values; a relation field, whose id usually ends in '_value', takes the related document's relative_url as a string).",
 "parameters": {
 "type": "object",
 "properties": {
 "relative_url": {
 "type": "string",
 "description": "relative_url of the module or existing document to act on"
 },
 "action_id": {
 "type": "string",
 "description": "id of the action to invoke: a workflow transition (e.g. 'confirm', 'start', 'validate'), a custom object action, or 'add <portal_type>' (e.g. 'add Purchase Order Line') to create a new document of that portal_type inside relative_url"
 },
 "dry_run": {
 "type": "boolean",
 "description": "If true (default), do not invoke or create anything: just return a preview. Set to false to actually do it."
 }
 },
 "required": [
 "relative_url",
 "action_id"
 ]
 }
 }
 }
